float fractal(vec2 c){

  vec2 uv = vec2(gl_FragCoord.x / iResolution.x, gl_FragCoord.y / iResolution.y);
	uv -= 0.7;
	uv /= vec2(iResolution.y / iResolution.x, 1);

  const float B = 256.0;

  float n = 0.0;
  vec2 z = c;
  float maxIter = 200.;

  for(float i = 0.; i<maxIter; i++){

    z= vec2(z.x * z.x - z.y * z.y , sin(iTime)/50.+2.1 * z.x * z.y)+ vec2(-.8,.156);

    if(dot(z,z)>(B*B) ) break;
    n += 1.0;

    if( z.x * z.x + z.y *z.y >10000.){

      return i/maxIter;

      }

    }

    float sn = n -log(log(length(z))/log(B))/log(.1);

    return sn;

    return 1.;

  }

mat2 R2d(float r){return mat2(cos(r),-sin(r),sin(r),cos(r));}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 uv = vec2(gl_FragCoord.x / iResolution.x, gl_FragCoord.y / iResolution.y);
	uv -= 0.5;
	uv /= vec2(iResolution.y / iResolution.x, 1);

  vec2 R2d = uv*R2d(ceil(iTime*1.1));


  vec2 p = (gl_FragCoord.xy -.5 * vec2(iResolution.x,iResolution.y))/1000.;

  float sn =fractal(p-R2d);

  vec3 col = 0.5 + 0.5 * cos(iTime+ uv.xyx+vec3(0,3,3));
  vec3 col2 = vec3(0)*2.;

  float color = fractal(p-R2d*sn);

  vec3 color2 = vec3(color);

  vec3 color3 = vec3(0)*4.;

  vec3 color4 = min(color2,color2);

  vec3 final =min(col,color4);

    fragColor = vec4(final,0.);
}
